// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address user, uint128 amount1, uint128 amount2) public {
        vm.assume(user != address(0));
        vm.assume(amount1 > 0 && amount2 > 0);
        uint256 am1 = amount1;
        uint256 am2 = amount2;

        vm.deal(user, am1 + am2);

        vm.prank(user);
        c.addToBalance{value: am1}();
        uint256 balanceAfterFirst = c.getBalance(user);

        vm.prank(user);
        c.addToBalance{value: am2}();
        uint256 balanceAfterSecond = c.getBalance(user);

        assertTrue(balanceAfterSecond >= balanceAfterFirst + am2);
    }
}
